import { processBatch } from '../src/ingest.mjs';

try {
  const args = process.argv.slice(2);
  if (args.length < 3 || args.length > 4) {
    throw new Error('Usage: node bin/ingest.mjs INPUT OUTPUT CHECKPOINT [BATCH_SIZE]');
