// Moves a corrupt checkpoint aside as evidence. Never overwrites earlier evidence.
async function quarantineCheckpoint(checkpointPath) {
  const directory = join(dirname(checkpointPath), 'recovery');
  await mkdir(directory, { recursive: true });
  let target = join(directory, 'checkpoint.bad.json');
  for (let n = 1; ; n++) {
    try {
      await link(checkpointPath, target);
      break;
    } catch (error) {
      if (error.code !== 'EEXIST') throw error;
      target = join(directory, `checkpoint.bad.${n}.json`);
    }
  }
  await rm(checkpointPath, { force: true });
  return target;
}

export async function processBatch({ inputPath, outputPath, checkpointPath, batchSize = 4 }) {
  if (!Number.isSafeInteger(batchSize) || batchSize <= 0) {
    throw new RangeError('batchSize must be a positive safe integer');
  }
  let nextLine = 0;
  try {
    ({ nextLine } = JSON.parse(await readFile(checkpointPath, 'utf8')));
    if (!Number.isSafeInteger(nextLine) || nextLine < 0) throw new Error('Invalid checkpoint nextLine');
  } catch (error) {
    if (error.code === 'ENOENT') {
      nextLine = 0;
    } else if (error instanceof SyntaxError || error.message === 'Invalid checkpoint nextLine') {
      // Replay from the start; output identities prevent duplicate appends.
      await quarantineCheckpoint(checkpointPath);
      nextLine = 0;
    } else {
      throw error;
    }
  }

